@@ -0,0 +1,29 @@
+// API keys and roles. A request carries `Authorization: Bearer <key>`; the key
+// is looked up in the store's `apiKeys`. Roles: viewer (GET only), cook (plus
+// cooking, waste, temperatures and stock-take counts) and manager (all).
+import { AppError } from "../errors.js";
+
+const COOK_ROUTES = [
+  ["POST", /^\/recipes\/[^/]+\/cook$/],
+  ["POST", /^\/batches\/[^/]+\/waste$/],
+  ["POST", /^\/temperatures$/],
+  ["POST", /^\/stocktakes\/[^/]+\/counts$/],
+];
+
+/** The API key record for the request's bearer token; throws `unauthorized` if none matches. */
+export function authenticate(store, headers) {
+  const header = headers.authorization ?? headers.Authorization ?? "";
+  const m = /^Bearer\s+(\S+)$/i.exec(String(header));
+  const found = m && store.data.apiKeys.find((k) => k.key === m[1]);
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** Throws `forbidden` unless the key's role may make this request. */
+export function authorize(key, method, path) {
+  if (key.role === "manager") return;
+  if (path === "/audit") throw new AppError("forbidden");
+  if (method === "GET") return;
+  if (key.role === "cook" && COOK_ROUTES.some(([m, re]) => m === method && re.test(path))) return;
+  throw new AppError("forbidden");
+}
